def compute(vars):
    carrying_value = vars["v1"]
    fair_value = vars["v2"]

    if fair_value == 0:
        return None

    difference = fair_value - carrying_value
    value = (difference / fair_value) * 100

    return {
        "value": value,
        "trace": {
            "carrying_value": carrying_value,
            "fair_value": fair_value,
            "difference": difference,
            "ratio": difference / fair_value,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
